function parentheticalTextAreaChanged() {
    parenValue = $("#parenthetical")[0].value;
    filenameValue = $("#file")[0].value;

    if(filenameValue == '' && parenValue == '') {
        disableCreateNetworkButton();
    } else {
        enableCreateNetworkButton();
    }
}

function enableCreateNetworkButton() {
    $("#createNetwork")[0].disabled = false;
    $("#createNetwork").removeClass("disabled");
}
function disableCreateNetworkButton() {
    $("#createNetwork")[0].disabled = true;
    $("#createNetwork").addClass("disabled");
}

function showTab(tabLabel) {
    if(tabLabel == 'input') {
        $("#input-tab-contents").removeClass("d-none");
        $("#input-tab").addClass("active");
    } else {
        $("#input-tab-contents").addClass("d-none");
        $("#input-tab").removeClass("active");
    }

    if(tabLabel == 'network') {
        $("#network-tab-contents").removeClass("d-none");
        $("#network-tab").addClass("active");
    } else {
        $("#network-tab-contents").addClass("d-none");
        $("#network-tab").removeClass("active");
    }

    if(tabLabel == 'style') {
        $("#style-tab-contents").removeClass("d-none");
        $("#style-tab").addClass("active");
    } else {
        $("#style-tab-contents").addClass("d-none");
        $("#style-tab").removeClass("active");
    }

    if(tabLabel == 'download') {
        $("#download-tab-contents").removeClass("d-none");
        $("#download-tab").addClass("active");
    } else {
        $("#download-tab-contents").addClass("d-none");
        $("#download-tab").removeClass("active");
    }
}

// Populates the "Displayed Leaves" box
function createboxes() {
    // Enable the create network button.
    createNetworkSelector.disabled = false;
    
    // Clear the box of removables
    console.log("REMOVING dl-removables");
    console.log($('.dl-removable'));
    $('.dl-removable').remove()
    
    // Add "All" to the list of leaves if it is not already there
    if($("#__All__").length == 0) {
        // Add "All" to the list of leaves
        var linebreak = document.createElement("hr");
        var checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.name = "__All__";
        checkbox.id = "__All__";
        checkbox.value = "__All__";
        checkbox.checked = true;
        checkbox.onclick = allCheckboxChanged;

        paraDiv = document.createElement("p");
        paraDiv.appendChild(document.createTextNode("(All)"));
        displayedLeaves.appendChild(linebreak);
        displayedLeaves.appendChild(checkbox);
        displayedLeaves.appendChild(paraDiv);
    }


    // Populate the list of leaves
    totalLeafNodes = [];
    btnUpdateNet.disabled = false;
    nodeVal.sort().forEach(function (element) {
        console.log("element: " + element);

        // Create all the new elements for the displayed leaves box
        var linebreak = document.createElement("hr");
        
        var checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.name = element;
        checkbox.id = element;
        checkbox.value = element;
        checkbox.checked = true;
        checkbox.onclick = leafNodeCheckChanged;

        paraDiv = document.createElement("p");
        var text = document.createTextNode("" + element);
        paraDiv.appendChild(text);
        
        // Set the new elements' classes so they can be easily removed later
        // the setAttributes('from', element); makes it easy to filter out the individual
        // elements with JQuery when the user is searching
        linebreak.className = checkbox.className = paraDiv.className = text.className = "dl-removable";
        linebreak.setAttribute('from', element.toLowerCase());
        checkbox.setAttribute('from', element.toLowerCase());
        paraDiv.setAttribute('from', element.toLowerCase());

        // add all the leaves to the list
        if (!paraDiv.textContent.includes("Hash")) {
            totalLeafNodes.push(paraDiv.textContent);
        }
        if (!paraDiv.textContent.includes("Hash") && !paraDiv.textContent.includes("internal")) {
            displayedLeaves.appendChild(linebreak);
            displayedLeaves.appendChild(checkbox);
            displayedLeaves.appendChild(paraDiv);
        }
    });

    filterLeafBox();
}

function allCheckboxChanged() {
    var checked = $("#__All__")[0].checked;
    $("input.dl-removable").each(function(idx, i) {
        i.checked = checked;
    });
}

// Function run when the checkbox on a leaf node changes
// used to auto-uncheck the (All) checkbox
function leafNodeCheckChanged() {
    // Check if everything is checked
    var allTrue = true;
    $("input.dl-removable").each(function(idx, i) {
        allTrue = allTrue && i.checked;
    });

    // Check or uncheck everything
    if(!allTrue) {
        $("#__All__")[0].checked = false;
    } else {
        $("#__All__")[0].checked = true;
    }
}

function filterLeafBox() {
    // TODO: case doesn't matter
    // get the user's search input
    var searchText = $('.input')[0].value.toLowerCase();

    // filter everything that does not match this
    if(searchText == "") {
        $('.dl-removable').show();
    } else {
        $('.dl-removable:not([from*="' + searchText + '"])').hide();
        $('.dl-removable[from*="' + searchText + '"]').show();
    }
}


// resizes the SVG to fit its content whenever the window is resized
function resizeSVG() {
    width = $("#svg-container").width();
    height = window.innerHeight - $("#navbar-id-height-getter").height() - $("footer").height() - 82;
    height = Math.max(height, 0);

    // Adjusting the width here affects the svg's container, so we
    // need to resize twice to actually fit to the content
    $("#chartId").attr("width", width).attr("height", height);
    width = $("#svg-container").width();
    $("#chartId").attr("width", width).attr("height", height);

    console.log("".concat(width, " x ", height))
}
window.addEventListener("resize", resizeSVG);


// called when the "Create Network" button is pressed;
// does all the calls that populate the D3 graph
function onClickCreateNetwork() {
    $("#createNetwork").addClass("disabled");

    // change the icon to the loading icon
    $("#create-network-loading-icon").removeClass("d-none");
    $("#create-network-notloading-icon").addClass("d-none");

    var svg = d3.select("body").select("svg")

    // don't let the user press the create network button again while we're working...
    createNetworkSelector.disabled = true;

    // show the loading icon and clear out any previous warning messages
    document.getElementById("instruct").innerHTML = "";
    
    // ------------------------------------------------------------------------------------------
    // according to which input type is selected, push the input data to the server,
    // and then generate the Displayed Leaves box
    // each of the `pushXToServer(...)` functions will call `createD3Graph` if no errors occur
    // ------------------------------------------------------------------------------------------
    // if we're reading parenthetical text, that's easy; do that and leave.
    if(selectedDropDown == "pf" && newickField.value != "") {
        pushParentheticalToServer(newickField.value);
        return;
    } else if(newickField.value == "" && currFile == undefined) {
        // there is no input yet.
        document.getElementById("instruct").innerHTML = "No input selected; please select some input then try again.";
        // document.getElementById("loader").style.visibility = "hidden";
        return;
    }
    
    // otherwise, we need a file reader
    var fr = new FileReader();
    fr.onload = function() {
        // read the text and get rid of carriage returns
        fileText = fr.result.replaceAll("\r", "");
        
        // if the user input is bad, quit the fxn. the `testUserInput` fxn will
        // provide the proper error message on its own
        if (testUserInput(selectedDropDown) > 0) {
            return;
        }
        
        // process data w/ the appropriate fxn
        if(selectedDropDown == "pf") {
            console.log("----");
            console.log(fileText);
            console.log("----");
            pushParentheticalToServer(fileText);
        } else if(selectedDropDown == "HYDE format") {
            pushHydeToServer(fileText, textThresh.value, newickField.value);
        } else {
            // triplets
            pushTripletsToServer(fileText);
        }
    }
    fr.readAsText(currFile);
}

// called when "Update Network" is pressed; only selected leaves are kept in the network
function updateNetwork() {
    $("#reroot-button").addClass("disabled");

    // disable Create/Update network buttons while we work...
    createNetworkSelector.disabled = true;
    // document.getElementById("loader").style.visibility = "visible";

    // gather which nodes are to be removed
    var removed_nodes = [];
    // we filter here so that we don't look at (All)
    var children = $("#displayed-leaves").children().filter(".dl-removable");
    for(var i = 0; i < children.length / 3; i++) {
        // is the check box checked?
        if(!children[i*3+1].checked) {
            // no: this node gets removed
            removed_nodes.push(children[i*3+2].innerHTML);
        }
    }

    // get the new root, if there is one
    if(highlightedNode != null) {
        new_root_full = highlightedNode.id;
        new_root = highlightedNode.id;
        if(new_root.startsWith("internal")) {
            new_root = new_root.substr(8, new_root.length - 8)
        }
    } else {
        new_root = "";
        new_root_full = "";
    }


    // TODO: do a bad request that is guaranteed to cause an error to see how the server responds and
    //       to see what is returned in the request.

    // send the server request for executing user adjustments
    var data = JSON.stringify({
        "text":originalNewick,
        "removed_nodes":removed_nodes,
        "new_root":new_root
    })

    var request = new XMLHttpRequest();
    request.open("POST", "http://127.0.0.1:5001/getUserAdjustedParenthetical/");
    request.setRequestHeader("Content-Type", "application/json");
    request.addEventListener("readystatechange", processRequest, false);
    request.send(data);

    function processRequest(e) {
        if(request.readyState == 4 && request.status == 200) {
            var x = JSON.parse(request.responseText);
            console.log(x);
            console.log('rootname' in x)
            console.log('new_root' in x)

            if(x.result == 'success') {
                // change to new root
                if('rootname' in x) {
                    ROOT_NAME = x['rootname'];
                } else if('new_root' in x) {
                    ROOT_NAME = x['new_root'];
                }
                
                // reset highlighted node var
                highlightedNode = null;

                // push the parenthetical
                pushParentheticalToServer(x.newick, false);
        
                // re-enable Create/Update network buttons
                createNetworkSelector.disabled = false;
                btnUpdateNet.disabled = false;
                rerootButton.disabled = true;
            } else {
                // failure!!
                alert("An error occurred: ", x['errmsg']);
                console.log(x['errmsg']);
            }
        } else if(request.readyState == 4) {
            console.log("ready state == 4");
        } else if(request.status == 401) {
            console.log("401");
        }
    }
}


// clear the chart
function removeGraph() {
    $("#chartId").empty();
    setupLegend();
}

// to change node colors upon user update
function triggerColorChange(whichNodes) {
    if(whichNodes == 'root') {
        ROOT_COLOR = $("#root_color")[0].value;
    } else if(whichNodes == 'leaf') {
        LEAF_COLOR = $("#leaf_color")[0].value;
    } else if(whichNodes == 'hybrid') {
        HYBRID_COLOR = $("#hybrid_color")[0].value;
    } else if(whichNodes == 'internal') {
        INTERNAL_COLOR = $("#internal_color")[0].value;
    } else if(whichNodes == 'named internal') {
        INTERNAL_NAMED_COLOR = $("named_internal_color")[0].value;
    }

    // reset all circle colors (except for the legend circles)
    svg.selectAll("circle").filter(":not(.legend-item)").style("fill", function (d) {
        try {
            var valueOfNode = d.id.toString();

            return isHybridNode(valueOfNode)
                ? HYBRID_COLOR
                : isRootNode(valueOfNode)
                ? ROOT_COLOR
                : isInternalNode(valueOfNode)
                ? INTERNAL_COLOR
                : isNamedInternalNode(valueOfNode)
                ? INTERNAL_NAMED_COLOR
                : LEAF_COLOR;
        } catch(exceptVar) {
            console.log(exceptVar);
            return "#000000";
        }
    });

    lcircs = svg.selectAll("circle").filter(".legend-item");
    lcircs.filter(".legend-leaf").style("fill", LEAF_COLOR);
    lcircs.filter(".legend-hybrid").style("fill", HYBRID_COLOR);
    lcircs.filter(".legend-internal").style("fill", INTERNAL_COLOR);
    lcircs.filter(".legend-root").style("fill", ROOT_COLOR);
}


